import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Player troubleshooting","description":"","frontmatter":{"pageId":"players/troubleshooting","contentRevision":1},"headers":[],"relativePath":"en/players/troubleshooting.md","filePath":"en/players/troubleshooting.md"}'),s={name:"en/players/troubleshooting.md"};function i(n,e,l,d,c,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="player-troubleshooting" tabindex="-1">Player troubleshooting <a class="header-anchor" href="#player-troubleshooting" aria-label="Permalink to &quot;Player troubleshooting&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Check</th></tr></thead><tbody><tr><td>Multiplayer missing</td><td>Game/Harmony versions, enabled mods, nested folders</td></tr><tr><td>Certificate refusal</td><td>Address, system time, confirmed pin; do not disable TLS</td></tr><tr><td>Modpack mismatch</td><td>Order, versions, hash, settings; apply with game closed</td></tr><tr><td>Transfers refused</td><td>Console/beacons, eligible goods, debt, threat, freeze</td></tr><tr><td>Live stuck after a drop</td><td>Wait for reconnect, check host connection, request snapshot</td></tr><tr><td>Coop busy</td><td>One active partner, owner online at home, eligible assigned pawns</td></tr></tbody></table><p>First preserve the exact error, time, server, action and operation ID. Diagnostic export creates a local ZIP; inspect it before independently sending it to an administrator.</p><h3 id="export-a-local-report" tabindex="-1">Export a local report <a class="header-anchor" href="#export-a-local-report" aria-label="Permalink to &quot;Export a local report&quot;">​</a></h3><ol><li>Open <strong>Multiplayer → Diagnostics</strong> in the server list, or diagnostics from the in-game Rimlink overlay. The snapshot is captured when opened; close/reopen to refresh.</li><li>Inspect the preview and choose <strong>Save local ZIP</strong>. The destination is shown before saving and the filename afterwards. Reports go under <code>Rimlink/Diagnostics</code> inside the game&#39;s save-data directory; the ZIP contains diagnostics.json and bounded events.log without free-form messages.</li><li>The default Windows profile is <code>%USERPROFILE%/AppData/LocalLow/Ludeon Studios/RimWorld by Ludeon Studios</code>; the separate game log is <code>Logs/Player.log</code>. A custom -savedatafolder changes this location. The report does not include that log; agree on a safe excerpt separately if required.</li></ol><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Diagnostics are not uploaded automatically and do not include Player.log or arbitrary logs. Game logs may contain personal data: do not publish them wholesale. Do not delete recovery journals or trust unknown certificates.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./connect">Connecting and signing in</a></li><li><a href="./saves-recovery">Saves and recovery</a></li><li><a href="./../admins/troubleshooting">Administrator troubleshooting</a></li></ul>',11)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
